import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let P(x) and Q(x) be distinct real polynomials of degree {degree_n} whose coefficients of x^0, x^1, ..., x^{degree_n} are all nonzero. Let r be the total multiplicity of their common real roots, and let s be the number of indices j in {0,1,...,{degree_n}} for which the coefficient of x^j in P equals the coefficient of x^j in Q. Determine the maximum possible value of r + s.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose a moderately large degree to avoid trivial instances and ensure difficulty
# Retry if any constraints fail (none here beyond range)
n = rng.randint(40, 800)  # keep n sizeable; both even/odd occur often
return {'degree_n': n}

    def verifier(assign):
# Validate domain
if 'degree_n' not in assign:
    # Missing slot
    return (False, None)  # missing input
n = assign['degree_n']
if not isinstance(n, int):
    return (False, None)  # wrong type
if n < 4:
    return (False, None)  # too small; trivial edge cases not allowed
# Compute maximum r+s:
# Upper bound idea:
# Let s be the number of equal coefficients; then T(x)=P(x)-Q(x) has exactly (n+1 - s) nonzero terms.
# By Descartes' rule, a k-term real polynomial has at most k-1 positive roots and k-1 negative roots (multiplicity counted),
# so T has at most 2((n+1 - s) - 1) = 2(n - s) nonzero real roots.
# Because P and Q have nonzero constant terms, 0 cannot be a common root; hence r <= min(n-1, 2(n - s)).
# Therefore r + s <= min(n-1, 2(n - s)) + s. Optimizing over integer s in [0, n] yields
# max r+s = floor(3n/2) if n is odd, and (3n/2) - 1 if n is even.
if n % 2 == 0:
    answer = (3*n)//2 - 1
else:
    answer = (3*n - 1)//2  # floor(3n/2)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

